function formatUsPhoneNumber(input) {
  const original = typeof input === "string" || typeof input === "number" ? String(input) : "";
  let number = "";
  let extension = "";
  if (typeof input !== "number" || (Number.isSafeInteger(input) && input >= 0)) {
    const explicit = /^([+0-9(). -]+?)(?:\s*(?:ext\.?|x|#)\s*([0-9]+))?$/i.exec(original.trim());
    if (explicit) {
      const base = explicit[1].trim();
      const digits = base.replace(/\D/g, "");
      if (/^\+1[^+]*$/.test(base) || !base.includes("+")) {
        if (digits.length === 10 && !base.startsWith("+")) {
          number = "1" + digits;
          extension = explicit[2] ?? "";
        } else if (
          digits.length >= 11 &&
          digits.startsWith("1") &&
          (!explicit[2] || digits.length === 11)
        ) {
          number = digits.slice(0, 11);
          extension = explicit[2] ?? digits.slice(11);
        }
      }
    }
  }
  const extensionNumber = Number(extension);
  if (!Number.isSafeInteger(extensionNumber)) number = "";
  const area = number.slice(1, 4);
  const exchange = number.slice(4, 7);
  const local = number.slice(7);
  const national = number ? "(" + area + ") " + exchange + "-" + local : "";
  return {
    "Phone Number (Input)": original,
    "Phone Number": Number(number),
    "Phone Number (E-164)": number ? "+" + number : "",
    "Phone Number (National)": national,
    "Phone Number (Full National)": number ? "1 " + national : "",
    "Phone Number (International)": number ? "00-1-" + area + "-" + exchange + "-" + local : "",
    Extension: number ? extensionNumber : 0,
    "Extension (String)": number && extensionNumber ? String(extensionNumber) : "",
  };
}

return $input.all().map((item, index) => ({
  json: formatUsPhoneNumber(item.json["Phone Number"]),
  pairedItem: { item: index },
}));
